export const SYMPTOM_BY_ID = new Map(KB_SYMPTOMS.map((s) => [s.id, s]));
export const DISEASE_BY_ID = new Map(KB_DISEASES.map((d) => [d.id, d]));

/** 症状编码 -> 名称 */
export function symptomName(code: string) {
  return SYMPTOM_BY_ID.get(code)?.name ?? code;
}
/** 疾病编码 -> 子类型名称 */
export function diseaseName(code: string) {
  return DISEASE_BY_ID.get(code)?.name ?? code;
}
/** 疾病的症状名称列表 */
export function diseaseSymptomNames(d: KBDisease) {
  return d.symptoms.map(symptomName);
}
/** 稳定伪随机（用于演示统计，不参与业务逻辑） */
export function kbHash(s: string) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}
/** 近 7 天发病头数（演示数据，按编码稳定生成） */
export function recent7d(code: string) {
  const h = kbHash(code);
  return h % 5 === 0 ? 0 : h % 13;
}
/** 严重度（演示：按疾病分类推断） */
export function severityOf(d: KBDisease): "高" | "中" | "低" {
  if (d.catName.includes("子宫炎") || d.catName.includes("呼吸道")) return "高";
  if (d.catName.includes("代谢") || d.catName.includes("消化")) return "中";
  return kbHash(d.id) % 3 === 0 ? "中" : "低";
}
